_PARSED_CACHE: dict[tuple[str, int], list[tuple[int, int, int, str]]] = {}


def _get_parsed_runs(name: str, frame_idx: int) -> tuple[int, int, int, list[tuple[int, int, int, str]]]:
    spec = OFFICIAL_SPRITES.get(name) or OFFICIAL_SPRITES["pikachu"]
    frames = spec["frames"]
    f_idx = frame_idx % len(frames)
    key = (name, f_idx)
    runs = _PARSED_CACHE.get(key)
    if runs is None:
        pal = spec["palette"]
        runs = []
        raw = frames[f_idx]
        if raw:
            for row_part in raw.split("|"):
                ry_hex, segs = row_part.split(":", 1)
                ry = int(ry_hex, 16)
                for seg in segs.split(";"):
                    rx_h, run_h, ci_h = seg.split(",")
                    runs.append((int(rx_h, 16), ry, int(run_h, 16), pal[int(ci_h, 16)]))
        _PARSED_CACHE[key] = runs
    return spec["w"], spec["h"], spec["scale"], runs


def render_official_pokemon(
    name: str,
    cx: int,
    feet_y: int,
    anim_frame: int = 0,
    scale_override: int | None = None,
) -> tuple[str, int, int, int, int]:
    """Render authentic animated Pokémon sprite anchored at (cx, feet_y).
    Returns (svg_rects, x0, y0, pixel_w, pixel_h).
    """
    key = (name or "pikachu").strip().lower()
    if key not in OFFICIAL_SPRITES:
        key = "pikachu"
    w, h, default_scale, runs = _get_parsed_runs(key, anim_frame)
    sc = default_scale if scale_override is None else scale_override
    pw = w * sc
    ph = h * sc
    x0 = cx - pw // 2
    y0 = feet_y - ph
    rects = [
        f'<rect x="{x0 + rx * sc}" y="{y0 + ry * sc}" width="{run * sc}" height="{sc}" fill="{col}"/>'
        for rx, ry, run, col in runs
    ]
    return "".join(rects), x0, y0, pw, ph
